// n8n Code node "Validate submission"  (mode: Run Once for All Items)
//
// The FIRST step after the public Form Trigger, before Gemini, Firestore or
// Gmail. This is the only place the submission is really checked: the form's
// own "required" and "email" settings are enforced by the visitor's browser
// and can be bypassed by posting directly to the form URL.
//
// Output: ONE item.
//   valid: true  -> the cleaned values under the SAME field labels as the form,
//                   so downstream nodes read them from here, not from the raw form.
//   valid: false -> only `errors` (field + code, never the submitted text), and
//                   no values, so rejected content can't flow anywhere.
const MAX_NAME = 100;
const MAX_EMAIL = 254;
const MAX_MESSAGE = 5000;

const NAME = 'Your Name';
const EMAIL = 'Your Email';
const MESSAGE = 'What is it you would like us to fix ?';

const form = $('Form Trigger').first().json ?? {};
const errors = [];

// Control characters (incl. line breaks) have no place in a name or an address,
// and a line break in an address is how mail-header injection is attempted.
const CONTROL = /[\u0000-\u001f\u007f]/;

function field(label, key, max, { allowNewlines }) {
  const raw = form[label];
  if (raw === undefined || raw === null) {
    errors.push({ field: key, code: 'missing' });
    return null;
  }
  if (typeof raw !== 'string') {
    errors.push({ field: key, code: 'not_text' });
    return null;
  }
  let v = raw.replace(/\r\n?/g, '\n');
  if (!allowNewlines) {
    if (CONTROL.test(v)) {
      errors.push({ field: key, code: 'invalid_characters' });
      return null;
    }
    v = v.replace(/\s+/g, ' ');
  } else {
    // Keep line breaks and tabs in a message, drop every other control character.
    v = v.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');
  }
  v = v.trim();
  if (!v) {
    errors.push({ field: key, code: 'empty' });
    return null;
  }
  if (v.length > max) {
    errors.push({ field: key, code: 'too_long', max });
    return null;
  }
  return v;
}

const name = field(NAME, 'name', MAX_NAME, { allowNewlines: false });
const email = field(EMAIL, 'email', MAX_EMAIL, { allowNewlines: false });
const message = field(MESSAGE, 'message', MAX_MESSAGE, { allowNewlines: true });

// A practical address check (not full RFC 5322): one "@", a dotted domain,
// no spaces and none of , ; < > ( ) " \ in it.
if (email !== null) {
  const at = email.indexOf('@');
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  const ok =
    at > 0 &&
    at === email.lastIndexOf('@') &&
    local.length <= 64 &&
    !/[\s,;<>()"\\]/.test(email) &&
    /^[^.][^\s]*\.[^.\s]+$/.test(domain) &&
    !domain.includes('..') &&
    !local.startsWith('.') &&
    !local.endsWith('.') &&
    !local.includes('..') &&
    !domain.split('.').some((p) => !p || p.startsWith('-') || p.endsWith('-'));
  if (!ok) errors.push({ field: 'email', code: 'invalid_format' });
}

if (errors.length) return [{ json: { valid: false, errors } }];

return [{ json: { valid: true, errors: [], [NAME]: name, [EMAIL]: email, [MESSAGE]: message } }];

// n8n Code node "Select active articles"  (mode: Run Once for All Items)
//
// Input:  every document the Firestore "Get many documents" node returned
//         from `knowledge_base` (one item per article; possibly none).
// Output: EXACTLY ONE item. That is what stops the rest of the workflow from
//         running once per article (and creating one ticket per article).
//
// - Inactive articles (active !== true) are dropped.
// - Each article keeps its metadata (id, title, category, keywords) so the
//   model can cite the right section and tell articles apart.
const isTrue = (v) => v === true || (typeof v === 'string' && v.trim().toLowerCase() === 'true');
const text = (v) => (typeof v === 'string' ? v.trim() : '');
const keywords = (a) =>
  Array.isArray(a.keywords)
    ? a.keywords.filter((k) => typeof k === 'string' && k.trim()).join(', ')
    : text(a.keywords);

const items = $input.all();
// The Firestore node is set to "continue on error": a failed read arrives as an
// item carrying `error`. That must not be mistaken for "no articles exist".
const kbUnavailable = items.some((item) => item.json && item.json.error);

const articles = items
  .map((item) => item.json)
  .filter((a) => a && isTrue(a.active) && text(a.content));

const knowledgeBase = articles.length && !kbUnavailable
  ? articles
      .map((a, i) =>
        [
          `### ARTICLE ${i + 1} of ${articles.length}`,
          `ID: ${a._id ?? a.id ?? 'unknown'}`,
          `Title: ${text(a.title) || '(untitled)'}`,
          `Category: ${text(a.category) || '(none)'}`,
          `Keywords: ${keywords(a) || '(none)'}`,
          'Content:',
          text(a.content),
        ].join('\n'),
      )
      .join('\n\n---\n\n')
  : 'NO ACTIVE KNOWLEDGE-BASE ARTICLES ARE AVAILABLE.';

return [
  {
    json: {
      knowledgeBase,
      articleCount: kbUnavailable ? 0 : articles.length,
      kbUnavailable,
      articleTitles: articles.map((a) => text(a.title) || a._id || 'unknown'),
    },
  },
];

// n8n Code node "Build ticket"  (mode: Run Once for All Items)
//
// Produces EXACTLY ONE ticket per form submission and NEVER throws, so a Gemini
// or knowledge-base failure can no longer lose the customer's submission. The
// Gemini and Firestore-read nodes are set to "continue on error"; whatever
// they return is validated here.
//
// Rules (the dashboard applies the same ones: see approvalRequired in
// src/lib/overview.ts):
//  1. Priority and category must be one of the known values (case and spacing
//     are normalised; nothing else is accepted or guessed).
//  2. Only Low and Medium may be handled automatically. High, Urgent, missing
//     or invalid priority => human review.
//  3. Human review is ALSO required when the knowledge base does not cover the
//     issue (kbStatus "not_covered", or no active articles) or the model says
//     escalationRequired, and when classification or evaluation failed.
//  4. When a model step failed we store only what the customer submitted plus
//     `intakeIssue`. No classification and no customer response is invented.
//  5. An automatic answer is only possible when ALL of this holds: Low/Medium,
//     kbStatus covered or partially_covered, escalationRequired false, no
//     intakeIssue, and a response exists. Otherwise escalationStatus is
//     "required", which sends the ticket to staff and sends the customer nothing.
//  6. The document ID is DETERMINISTIC (see ticketIdFor): the same submission within the same hour
//     always maps to the same ID, so a double submit or a retried write cannot create two tickets.
//     `intakeExecutionId` lets the workflow tell "my own earlier attempt" from "someone else's".
// Cleaned, validated values (same labels as the form). Nothing reaches this node unless
// 'Validate submission' accepted it.
const form = $('Validate submission').first().json;

const PRIORITIES = { low: 'Low', medium: 'Medium', high: 'High', urgent: 'Urgent' };
const CATEGORIES = {
  bug: 'Bug',
  'feature request': 'Feature Request',
  question: 'Question',
  other: 'Other',
};
const SENTIMENTS = { positive: 'Positive', neutral: 'Neutral', negative: 'Negative' };
const KB_STATUSES = {
  covered: 'covered',
  partially_covered: 'partially_covered',
  not_covered: 'not_covered',
};
const canon = (map, v) =>
  typeof v === 'string' ? (map[v.trim().toLowerCase().replace(/\s+/g, ' ')] ?? null) : null;

function modelObject(nodeName) {
  try {
    const raw = $(nodeName).first().json?.content?.parts?.[0]?.text;
    if (typeof raw !== 'string' || !raw.trim()) return null;
    const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    const obj = JSON.parse(cleaned);
    return obj && typeof obj === 'object' && !Array.isArray(obj) ? obj : null;
  } catch {
    return null;
  }
}
const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : undefined);
const list = (v) =>
  Array.isArray(v)
    ? v.filter((x) => typeof x === 'string' && x.trim())
    : typeof v === 'string' && v.trim()
      ? [v]
      : [];

// ---- deterministic ticket ID
// Pure-JS SHA-256: n8n's Code node does not allow require('crypto') unless the operator enables it.
function sha256Hex(text) {
  const bytes = [];
  const utf8 = unescape(encodeURIComponent(text));
  for (let i = 0; i < utf8.length; i++) bytes.push(utf8.charCodeAt(i));
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 0xff);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (bytes[off + 4 * i] << 24) | (bytes[off + 4 * i + 1] << 16) | (bytes[off + 4 * i + 2] << 8) | bytes[off + 4 * i + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}
// Same customer email + same message text within the same clock hour => same ID. A bucket
// boundary can still let one repeat through; a genuinely new message always gets a new ID.
const ticketIdFor = (email, message, nowMs) =>
  'tk_' +
  sha256Hex(
    [String(email).trim().toLowerCase(), String(message).replace(/\s+/g, ' ').trim(), Math.floor(nowMs / 3600000)].join('\n'),
  ).slice(0, 32);

let kb = { articleCount: 0, kbUnavailable: true }; // unknown => treat as unavailable
try {
  kb = $('Select active articles').first().json ?? kb;
} catch {
  /* keep the safe default */
}

// ---- classification
const cls = modelObject('Message a model');
const priority = canon(PRIORITIES, cls?.priority);
const category = canon(CATEGORIES, cls?.category);
let intakeIssue = !cls
  ? 'classification_failed'
  : !priority || !category
    ? 'classification_invalid'
    : undefined;

// ---- knowledge-base evaluation
const noKnowledge = kb.kbUnavailable === true || !(kb.articleCount > 0);
const ev = modelObject('Message a model1');
const kbStatusRaw = canon(KB_STATUSES, ev?.kbStatus);
const evalUsable =
  !!ev &&
  !!kbStatusRaw &&
  typeof ev.escalationRequired === 'boolean' &&
  typeof ev.customerResponse === 'string' &&
  ev.customerResponse.trim().length > 0;

let kbFields;
if (noKnowledge) {
  // Nothing to answer from: the model's text (if any) is discarded.
  if (kb.kbUnavailable === true) intakeIssue = intakeIssue ?? 'knowledge_base_unavailable';
  kbFields = {
    kbStatus: 'not_covered',
    coverageReason:
      kb.kbUnavailable === true
        ? 'The knowledge base could not be read, so no automatic answer was given.'
        : 'There are no active knowledge-base articles, so this issue is not covered.',
    supportedSteps: [],
    unsupportedParts: [],
    escalationRequired: true,
  };
} else if (!cls || !evalUsable) {
  // No classification at all: the evaluation was made without one, so it is not used either.
  intakeIssue = intakeIssue ?? (ev ? 'evaluation_invalid' : 'evaluation_failed'); // classification_failed wins when set
  kbFields = {
    coverageReason: 'The knowledge-base evaluation did not complete, so no automatic answer was given.',
    supportedSteps: [],
    unsupportedParts: [],
    escalationRequired: true,
  };
} else {
  const notCovered = kbStatusRaw === 'not_covered';
  kbFields = {
    kbStatus: kbStatusRaw,
    relevantSection: notCovered ? null : (str(ev.relevantSection) ?? null),
    coverageReason: str(ev.coverageReason),
    // Never keep steps for an issue the knowledge base doesn't cover.
    supportedSteps: notCovered ? [] : list(ev.supportedSteps),
    unsupportedParts: list(ev.unsupportedParts),
    escalationRequired: notCovered ? true : ev.escalationRequired === true,
    customerResponse: ev.customerResponse.trim(),
  };
}

// ---- routing: one decision
const autoPriority = priority === 'Low' || priority === 'Medium';
const humanReview =
  !autoPriority ||
  kbFields.escalationRequired === true ||
  kbFields.kbStatus === 'not_covered' ||
  !!intakeIssue ||
  !kbFields.customerResponse;

let escalationReason = 'Normal priority handling';
if (intakeIssue) {
  escalationReason = `Automatic processing did not complete (${intakeIssue}): manual handling required`;
} else if (priority === 'High' || priority === 'Urgent') {
  escalationReason = 'High-priority ticket requires faster attention';
} else if (!autoPriority) {
  escalationReason = 'Priority missing or invalid: human review required';
} else if (kbFields.kbStatus === 'not_covered' || kbFields.escalationRequired === true) {
  escalationReason = 'The knowledge base does not support an automatic answer: human review required';
} else if (!kbFields.customerResponse) {
  escalationReason = 'No response was generated: human review required';
}

const nowDate = new Date();
const now = nowDate.toISOString();
let executionId;
try {
  executionId = $execution.id === undefined || $execution.id === null ? undefined : String($execution.id);
} catch {
  executionId = undefined;
}
const ticket = {
  // Document ID for the Firestore node (not a stored column) and the run that built this ticket.
  ticketId: ticketIdFor(form['Your Email'], form['What is it you would like us to fix ?'], nowDate.getTime()),
  intakeExecutionId: executionId,

  // The customer's submission, always preserved exactly
  customerName: form['Your Name'],
  customerEmail: form['Your Email'],
  message: form['What is it you would like us to fix ?'],

  // Classification (only validated values)
  category: category ?? undefined,
  reason: cls ? str(cls.reason) : undefined,
  sentiment: cls ? canon(SENTIMENTS, cls.sentiment) ?? undefined : undefined,
  priority: priority ?? undefined,
  summary: cls ? str(cls.summary) : undefined,

  // Knowledge-base evaluation
  ...kbFields,

  // aiResponse kept for compatibility
  aiResponse: kbFields.customerResponse,

  status: 'pending_review',
  createdAt: now,

  escalationStatus: humanReview ? 'required' : 'not_required',
  escalationReason,
  // The dashboard recomputes approval from the same rule; this value is ignored for Low/Medium.
  reviewStatus: 'awaiting_review',
};
if (intakeIssue) ticket.intakeIssue = intakeIssue;
if (humanReview) ticket.escalatedAt = now;

// Drop undefined keys so the Firestore node never receives them.
for (const k of Object.keys(ticket)) if (ticket[k] === undefined) delete ticket[k];

return [{ json: ticket }];

// n8n Code node "Prepare email fields"  (mode: Run Once for All Items)
//
// Customer and model text goes into HTML emails (some to staff), so it is
// HTML-escaped here once, and the templates only use `$json.safe.*`.
const t = $input.first().json;
// The Create node normally returns `_id`; when this item came from the duplicate-recovery path
// it did not, so fall back to the deterministic ticket ID from 'Build ticket'.
let ticketId = t._id ?? t.id ?? t.ticketId;
if (ticketId === undefined) {
  try {
    ticketId = $('Build ticket').first().json.ticketId;
  } catch {
    /* leave undefined */
  }
}

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
const list = (v) => (Array.isArray(v) ? v : typeof v === 'string' && v.trim() ? [v] : []);

const steps = list(t.supportedSteps);
const unsupported = list(t.unsupportedParts);
const na = (v) => (v === undefined || v === null || v === '' ? 'Not available' : v);
const cell = 'border-top:1px solid #ece6dc;';

const stepsHtml = steps.length
  ? steps
      .map(
        (s, i) =>
          `<tr><td width="40" style="vertical-align:top; padding:10px 0; ${cell} font-family:Georgia, serif; font-size:16px; color:#991b1b;">0${i + 1}</td>` +
          `<td style="vertical-align:top; padding:10px 0; ${cell} font-size:14px; line-height:1.65; color:#1f1a17;">${esc(s)}</td></tr>`,
      )
      .join('')
  : `<tr><td style="padding:10px 0; ${cell} font-size:14px; color:#4a423b;">None identified.</td></tr>`;

return [
  {
    json: {
      ...t,
      _id: ticketId,
      safe: {
        customerName: esc(t.customerName),
        customerEmail: esc(t.customerEmail),
        message: esc(t.message),
        category: esc(na(t.category)),
        priority: esc(na(t.priority)),
        sentiment: esc(na(t.sentiment)),
        summary: esc(na(t.summary)),
        kbStatus: esc(na(t.kbStatus)),
        relevantSection: esc(t.relevantSection ?? 'None'),
        coverageReason: esc(na(t.coverageReason)),
        escalationReason: esc(t.escalationReason),
        escalationStatus: esc(t.escalationStatus),
        customerResponse: esc(t.customerResponse),
        stepsHtml,
        unsupportedHtml: unsupported.length ? unsupported.map(esc).join('<br>') : 'None identified.',
        // Plain text for the subject line. Priority is only ever a validated value; "Unknown" when missing.
        subjectPriority: /^(Low|Medium|High|Urgent)$/.test(String(t.priority ?? '')) ? t.priority : 'Unknown',
        // Plain text for the subject line: no control characters or line breaks.
        subjectName: String(t.customerName ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, 80),
      },
    },
  },
];

// n8n Code node "Classify create error"  (mode: Run Once for All Items)
//
// Reached only from the ERROR output of "Create a document", after n8n's own retries.
// Nothing has been emailed yet. Decides whether Firestore refused the write because the
// document already exists (the deterministic ticket ID was used before) or failed for any
// other reason (outage, permissions, bad credential ...).
const j = $input.first().json ?? {};
const e = j.error ?? j;
const message = typeof e === 'string' ? e : String(e?.message ?? e?.description ?? JSON.stringify(e ?? {}));
const text = `${message} ${typeof e === 'object' ? JSON.stringify(e ?? {}) : ''}`;
const httpCode = Number(e && typeof e === 'object' ? (e.httpCode ?? e.statusCode ?? e.code) : NaN);
const conflict = httpCode === 409 || /already[ _-]?exists/i.test(text);
return [{ json: { kind: conflict ? 'conflict' : 'failure', error: message.replace(/\s+/g, ' ').slice(0, 300) } }];

// n8n Code node "Check existing ticket"  (mode: Run Once for All Items)
//
// The Create node refused because support_tickets/<ticketId> already exists. Two very different
// situations look identical to Firestore:
//   ours      the document was written by THIS run (an earlier attempt succeeded but its reply was
//             lost, so n8n retried). The ticket is safe; carry on to the emails.
//   duplicate the document belongs to another run: the same submission arrived twice. The first run
//             owns the emails, so this one stops without creating or sending anything.
//   unclear   the existing document could not be read: we cannot tell, so staff are told.
// A missing document arrives as an empty item ("Always Output Data"); an error item is a read failure.
const mine = $('Build ticket').first().json;
const existing = $input.first().json ?? {};

if (existing.error !== undefined || Object.keys(existing).length === 0) {
  return [{ json: { route: 'unclear', error: 'The existing ticket could not be read' } }];
}
const mineId = mine.intakeExecutionId === undefined ? '' : String(mine.intakeExecutionId);
if (mineId && String(existing.intakeExecutionId ?? '') === mineId) {
  return [{ json: { ...mine, route: 'ours' } }];
}
return [{ json: { route: 'duplicate' } }];

// n8n Code node "Prepare rescue email"  (mode: Run Once for All Items)
//
// One staff email for every situation where the automation could not finish normally and the
// customer's submission must not be lost. All values are HTML-escaped here; Gmail only prints
// `html`. The submission always comes from 'Build ticket' (validated, trimmed) and the failure
// text is shortened, so no stack trace or credential detail is forwarded.
//
// kind (decided from where the item came from):
//   ticket_not_saved        Firestore failed; no ticket exists; no email was sent to anyone
//   ticket_unclear          the ticket ID already existed but could not be confirmed
//   acknowledgement_failed  ticket saved; the customer's acknowledgement email failed
//   escalation_failed       ticket saved; the staff escalation email failed
//   rate_limit_unavailable  the spam-protection store failed (fail-closed): the submission was refused, no ticket
const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
const ran = (name) => {
  try {
    return $(name).isExecuted === true;
  } catch {
    return false;
  }
};

let t = {};
try {
  t = $('Build ticket').first().json ?? {};
} catch {
  // No ticket was built (the rate limiter refused the submission first): use the validated form values.
  try {
    const v = $('Validate submission').first().json ?? {};
    t = { customerName: v['Your Name'], customerEmail: v['Your Email'], message: v['What is it you would like us to fix ?'] };
  } catch {
    /* nothing to show */
  }
}
const input = $input.first().json ?? {};

let kind;
if (input.route === 'unavailable') kind = 'rate_limit_unavailable';
else if (input.route === 'unclear') kind = 'ticket_unclear';
else if (input.kind === 'failure') kind = 'ticket_not_saved';
else if (ran('Send a message1')) kind = 'acknowledgement_failed';
else if (ran('Send a message')) kind = 'escalation_failed';
else kind = 'ticket_not_saved';

const TEXT = {
  rate_limit_unavailable: {
    label: 'Spam check unavailable: request held',
    what: 'The rate limiter could not reach Firestore, so this submission was refused to avoid bypassing spam protection. No ticket was created and nothing was sent to the customer. The visitor was told to try again later.',
    todo: 'If this looks like a genuine request, handle it manually. Then check Firestore access to the rate_limits collection.',
  },
  ticket_not_saved: {
    label: 'Ticket NOT saved',
    what: 'The ticket could not be saved to Firestore, so it will not appear in the dashboard. No email was sent to the customer or to staff. The customer was shown a "submitted" message.',
    todo: 'Please handle this request manually and contact the customer.',
  },
  ticket_unclear: {
    label: 'Ticket status unclear',
    what: 'A ticket with this ID already exists but could not be confirmed as part of this submission. No email was sent.',
    todo: 'Check the dashboard for this customer. If there is no ticket, handle this request manually.',
  },
  acknowledgement_failed: {
    label: 'Customer acknowledgement failed',
    what: 'The ticket was saved, but the acknowledgement email to the customer could not be sent.',
    todo: 'The ticket is in the dashboard. Consider replying to the customer yourself.',
  },
  escalation_failed: {
    label: 'Escalation email failed',
    what: 'The ticket was saved, but the escalation email to the staff inbox could not be sent (this message is the fallback).',
    todo: 'The ticket is in the dashboard. Please review it now.',
  },
